// ==== AYARLAR — sadece burayı düzenleyin ====
const AYAR = {
  bitrixWebhook: 'https://xre.bitrix24.com.tr/rest/1/WEBHOOK_KODU/', // Bitrix24 gelen webhook (crm + user izinli). Sonunda / olsun
  bitrixPortal:  'https://xre.bitrix24.com.tr',
  bitrixMemberId: 'b18f228e772bb03010f6979a2856f0f8',  // Sadece bu portaldan gelen istekler kabul edilir
  telegramChatId: '-5591560509',
  smsMetni: 'XRE franchise başvurunuz alınmıştır. Danışmanımız en kısa sürede sizinle iletişime geçecektir.',
  epostaKonu: 'XRE Franchise Başvurunuz Alındı',
  ercell: {
    url: 'https://gateway.erccell.com.tr/corporatesms/sendsms/',
    kullanici: 'ERCELL_KULLANICI',
    sifre: 'ERCELL_SIFRE',
    baslik: 'XRE',
    smsTipi: 'UC',
    gonderimTipi: '1:N',
  },
};
// ============================================

// Bitrix robotu "document_id[2]=DEAL_123" gönderir; elle test için ?deal_id=123 de olur.
const b = $json.body || {};
const q = $json.query || {};
const docId = b['document_id[2]'] ?? b.document_id?.[2] ?? '';
const dealId = String(q.deal_id || b.deal_id || docId).replace(/\D/g, '');
if (!dealId) throw new Error('Anlaşma ID bulunamadı: ' + JSON.stringify(b).slice(0, 300));

const memberId = b['auth[member_id]'] ?? b.auth?.member_id;
if (memberId && memberId !== AYAR.bitrixMemberId) throw new Error('Yabancı Bitrix portalı: ' + memberId);

return [{ json: { ayar: AYAR, dealId } }];

const { ayar, dealId } = $('Bitrix İsteğini Oku').first().json;
const r = $json.result?.result || {};
const deal = r.deal || {};
const kisi = r.contact || {};
const u = (r.user || [])[0];
const asama = (r.stage || [])[0]?.NAME || deal.STAGE_ID || '-';

const ilk = a => (Array.isArray(a) && a.length ? a[0].VALUE : '') || '';
const adSoyad = [kisi.NAME, kisi.SECOND_NAME, kisi.LAST_NAME].filter(Boolean).join(' ') || deal.TITLE || '';
const telHam = ilk(kisi.PHONE) || deal.UF_CRM_1734685306767 || '';
const email = ilk(kisi.EMAIL) || deal.UF_CRM_1726650433488 || '';
const ulke = deal.UF_CRM_6A86B5EB10D28 || '';

let d = String(telHam).replace(/\D/g, '');
if (d.startsWith('0090')) d = d.slice(2);
if (d.startsWith('0')) d = '90' + d.slice(1);
if (d.length === 10 && d.startsWith('5')) d = '90' + d;
const telefonSms = d;
const telefon = d ? '+' + d : telHam;

const sorumlu = u ? [u.NAME, u.LAST_NAME].filter(Boolean).join(' ') : 'Atanmadı';
const sorumluTel = u ? (u.PERSONAL_MOBILE || u.WORK_PHONE || '') : '';
const kartLink = `${ayar.bitrixPortal}/crm/deal/details/${dealId}/`;
const kisiLink = kisi.ID ? `${ayar.bitrixPortal}/crm/contact/details/${kisi.ID}/` : '';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tarih = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

const telegramMetni = [
  '📝 <b>Yeni Franchise Formu Dolduruldu</b>',
  '',
  `👤 <b>Ad Soyad:</b> ${esc(adSoyad)}`,
  `📞 <b>Telefon:</b> ${telefon ? esc(telefon) : '<i>yok</i>'}`,
  `✉️ <b>E-posta:</b> ${email ? esc(email) : '<i>yok</i>'}`,
  ulke ? `🌍 <b>Ülke:</b> ${esc(ulke)}` : null,
  '',
  `🧑‍💼 <b>Sorumlu:</b> ${esc(sorumlu)}${sorumluTel ? ' (' + esc(sorumluTel) + ')' : ''}`,
  `📊 <b>Aşama:</b> ${esc(asama)}`,
  `🔗 <a href="${kartLink}">Bitrix Anlaşma #${dealId}</a>` + (kisiLink ? ` · <a href="${kisiLink}">Kişi #${kisi.ID}</a>` : ''),
  `🕒 ${tarih}`,
].filter(x => x !== null).join('\n');

const epostaHtml = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#222;line-height:1.6">
<p>Sayın ${esc(adSoyad)},</p>
<p>${esc(ayar.smsMetni)}</p>
<p>İlginiz için teşekkür ederiz.</p>
<p><b>XRE Gayrimenkul</b></p></div>`;

return [{ json: { ayar, dealId, adSoyad, telefon, telefonSms, email, ulke, sorumlu, kartLink, telegramMetni, epostaHtml } }];
